sys_ux_client_script.required_translations:
[
    {
        "message": "The entity filters have been deleted. Changes to the associated records (if any) will reflect after the profile generation job runs."
    }
]

sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {

    api.data.delete_records.execute({
        "table": api.context.props.table,
        "sysIds": api.context.props.sysIds
    });

    api.emit("RECORD#RELATED_LIST_REFRESH_REQUESTED", {
        relatedListName: api.context.props.relatedListName
    });

    if(api.context.props.table == 'sn_grc_enrichment_query'){
        helpers.translate("The entity filters have been deleted. Changes to the associated records (if any) will reflect after the profile generation job runs.").then((value) => {
            api.emit("RECORD_PAGE_TABS#ADD_NOTIFICATIONS", {
                items: [{
                    id: "alert1",
                    status: "info",
                    icon: "info-circle-outline",
                    content: value,
                    action: {
                        type: "acknowledge"
                    }
                }]
            });
        });
    }
    helpers.modal.close();
}
